import type { LoaderFunctionArgs } from "react-router";
import db from "../db.server";
import {
  corsOptions,
  corsJson,
  validateShop,
  sanitizeCss,
} from "~/lib/api.server";
import { checkRateLimit } from "~/lib/rate-limit.server";

// ---------------------------------------------------------------------------
// Cache
// ---------------------------------------------------------------------------

const CACHE_MAX_AGE = 300; // 5 minutes

// ---------------------------------------------------------------------------
// Default widget config
// Mirrors WidgetConfig Prisma model defaults exactly
// ---------------------------------------------------------------------------

const WIDGET_CONFIG_DEFAULTS = {
  displayMode: "popup",
  position: "bottom-right",
  triggerType: "button",
  primaryColor: "#000000",
  successColor: "#16a34a",
  errorColor: "#dc2626",
  backgroundColor: "#ffffff",
  textColor: "#111111",
  borderRadius: "8",
  heading: "Size Guide",
  placeholder: "Select your size",
  buttonText: "Find My Size",
  successMessage: "This size should fit you well!",
  errorMessage:
    "We couldn't determine your size. Please refer to the chart.",
  showRecommender: true,
  customCss: "",
} as const;

// ---------------------------------------------------------------------------
// Loader — GET /api/widget-config
// Query params: shop (required)
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return corsOptions();
  }

  const url = new URL(request.url);
  const shop = url.searchParams.get("shop");

  const shopError = validateShop(shop);
  if (shopError) return shopError;

  const rateLimitError = checkRateLimit("widget-config:" + shop!, 60);
  if (rateLimitError) return rateLimitError;

  try {
    const config = await db.widgetConfig.findUnique({ where: { shop: shop! } });

    const cacheHeaders = {
      "Cache-Control": `private, max-age=${CACHE_MAX_AGE}`,
    };

    if (!config) {
      // Return defaults when no config has been saved yet
      return corsJson({ config: WIDGET_CONFIG_DEFAULTS }, { headers: cacheHeaders });
    }

    return corsJson(
      {
        config: {
          displayMode: config.displayMode,
          position: config.position,
          triggerType: config.triggerType,
          primaryColor: config.primaryColor,
          successColor: config.successColor,
          errorColor: config.errorColor,
          backgroundColor: config.backgroundColor,
          textColor: config.textColor,
          borderRadius: config.borderRadius,
          heading: config.heading,
          placeholder: config.placeholder,
          buttonText: config.buttonText,
          successMessage: config.successMessage,
          errorMessage: config.errorMessage,
          showRecommender: config.showRecommender,
          customCss: sanitizeCss(config.customCss ?? ""),
        },
      },
      { headers: cacheHeaders },
    );
  } catch {
    return corsJson(
      { error: "Unable to load widget configuration. Please try again." },
      { status: 500 },
    );
  }
};

import type { LoaderFunctionArgs } from "react-router";
import db from "../db.server";
import { corsOptions, corsJson, validateShop } from "~/lib/api.server";
import { checkRateLimit } from "~/lib/rate-limit.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

interface ChartData {
  headers: string[];
  units: { default: string; available: string[] };
  rows: Record<string, string>[];
}

interface SizeChartResponse {
  id: string;
  name: string;
  category: string;
  type: string;
  data: ChartData;
  assignmentType?: string;
}

// ---------------------------------------------------------------------------
// Assignment priority lookup
// Priority: product (1) > collection (2) > product_type (3) > tag (4) > all (5)
// ---------------------------------------------------------------------------

const ASSIGNMENT_PRIORITY: Record<string, number> = {
  product: 1,
  collection: 2,
  product_type: 3,
  tag: 4,
  all: 5,
};

// ---------------------------------------------------------------------------
// Loader — GET /api/size-chart
// Query params: shop (required), productId?, collectionId?, chartId?
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  if (request.method === "OPTIONS") {
    return corsOptions();
  }

  const url = new URL(request.url);
  const shop = url.searchParams.get("shop");
  const chartId = url.searchParams.get("chartId");
  const productId = url.searchParams.get("productId");
  const collectionId = url.searchParams.get("collectionId");

  const shopError = validateShop(shop);
  if (shopError) return shopError;

  const rateLimitError = checkRateLimit("size-chart:" + shop!, 120);
  if (rateLimitError) return rateLimitError;

  try {
    // Direct lookup by chartId
    if (chartId) {
      const chart = await db.sizeChart.findFirst({
        where: { id: chartId, shop: shop!, status: "active" },
      });

      if (!chart) {
        return corsJson({ error: "Chart not found" }, { status: 404 });
      }

      const parsedData = parseChartData(chart.data);
      const response: SizeChartResponse = {
        id: chart.id,
        name: chart.name,
        category: chart.category,
        type: chart.type,
        data: parsedData,
      };

      return corsJson(response);
    }

    // Build lookup values from provided params
    // We'll fetch all active assignments for this shop and filter in priority order
    const lookupValues: Array<{ type: string; value: string }> = [];

    if (productId) {
      lookupValues.push({ type: "product", value: productId });
    }
    if (collectionId) {
      lookupValues.push({ type: "collection", value: collectionId });
    }

    if (lookupValues.length === 0) {
      return corsJson(
        { error: "At least one of chartId, productId, or collectionId is required" },
        { status: 400 },
      );
    }

    // Always include the wildcard "all" fallback
    lookupValues.push({ type: "all", value: "*" });

    // Fetch all assignments that could match, ordered by the chart's status
    const assignments = await db.chartAssignment.findMany({
      where: {
        shop: shop!,
        OR: lookupValues.map(({ type, value }) => ({
          assignmentType: type,
          assignmentValue: value,
        })),
      },
      include: {
        sizeChart: true,
      },
    });

    // Filter to only active charts and pick by priority
    const activeAssignments = assignments.filter(
      (a) => a.sizeChart.status === "active",
    );

    if (activeAssignments.length === 0) {
      return corsJson(
        { error: "No size chart found for the given product" },
        { status: 404 },
      );
    }

    // Sort by priority — lowest number = highest priority
    activeAssignments.sort((a, b) => {
      const pa = ASSIGNMENT_PRIORITY[a.assignmentType] ?? 99;
      const pb = ASSIGNMENT_PRIORITY[b.assignmentType] ?? 99;
      return pa - pb;
    });

    const best = activeAssignments[0];
    const parsedData = parseChartData(best.sizeChart.data);

    const response: SizeChartResponse = {
      id: best.sizeChart.id,
      name: best.sizeChart.name,
      category: best.sizeChart.category,
      type: best.sizeChart.type,
      data: parsedData,
      assignmentType: best.assignmentType,
    };

    return corsJson(response);
  } catch {
    return corsJson(
      { error: "Unable to load size chart. Please try again." },
      { status: 500 },
    );
  }
};

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function parseChartData(raw: string): ChartData {
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (
      parsed !== null &&
      typeof parsed === "object" &&
      !Array.isArray(parsed)
    ) {
      const obj = parsed as Record<string, unknown>;
      return {
        headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
        units:
          obj.units !== null &&
          typeof obj.units === "object" &&
          !Array.isArray(obj.units)
            ? (obj.units as { default: string; available: string[] })
            : { default: "in", available: ["in", "cm"] },
        rows: Array.isArray(obj.rows)
          ? (obj.rows as Record<string, string>[])
          : [],
      };
    }
  } catch {
    // fall through to default
  }
  return {
    headers: [],
    units: { default: "in", available: ["in", "cm"] },
    rows: [],
  };
}

