158	// ---------------------------------------------------------------------------
159	// Helpers
160	// ---------------------------------------------------------------------------
161	
162	function parseChartData(raw: string): ChartData {
163	  try {
164	    const parsed = JSON.parse(raw) as unknown;
165	    if (
166	      parsed !== null &&
167	      typeof parsed === "object" &&
168	      !Array.isArray(parsed)
169	    ) {
170	      const obj = parsed as Record<string, unknown>;
171	      return {
172	        headers: Array.isArray(obj.headers) ? (obj.headers as string[]) : [],
173	        units:
174	          obj.units !== null &&
175	          typeof obj.units === "object" &&
176	          !Array.isArray(obj.units)
177	            ? (obj.units as { default: string; available: string[] })
178	            : { default: "in", available: ["in", "cm"] },
179	        rows: Array.isArray(obj.rows)
180	          ? (obj.rows as Record<string, string>[])
181	          : [],
182	      };
183	    }
184	  } catch {
185	    // fall through to default
186	  }
187	  return {
188	    headers: [],
189	    units: { default: "in", available: ["in", "cm"] },
190	    rows: [],
191	  };
192	}
